python -c 'import numpy as np, pandas as pd; from sklearn.model_selection import LeaveOneOut, cross_val_predict; from sklearn.linear_model import LinearRegression, RidgeCV; from sklearn.pipeline import make_pipeline; from sklearn.preprocessing import StandardScaler; from sklearn.metrics import mean_absolute_error, mean_squared_error; d=pd.read_csv("b3_fatigue_target.csv"); q=d[(d.THT>30)&(d.CT==30)]; cols=[c for c in q.columns if c not in ["TT","target"]]; rows=[]
for key,g in q.groupby(cols):
 if len(g)>1:
  rec=dict(zip(cols,key)); rec["gain"]=-np.polyfit(g.TT,g.target,1)[0]; rec["n"]=len(g); rec["Tmin"]=g.TT.min(); rows.append(rec)
s=pd.DataFrame(rows); a=d.loc[d.target.eq(718)].iloc[0]; print("Matched groups:",len(s)); print("High C slopes:\n",s[s.C>=.5][["C","Cr","gain","n"]].to_string(index=False)); print("Models predict cooling gain in MPa per degree; validation leaves out each recipe group")
for fs in [["C"],["C","Cr"],["C","Cr","Ni","Mo"],["C","Cr","Ni","Mo","Mn","Si"]]:
 model=make_pipeline(StandardScaler(),RidgeCV(alphas=np.logspace(-2,3,25))); p=cross_val_predict(model,s[fs],s.gain,cv=LeaveOneOut()); model.fit(s[fs],s.gain); gain=model.predict(a[fs].to_frame().T)[0]; print(fs,"LOO MAE",round(mean_absolute_error(s.gain,p),3),"LOO RMSE",round(mean_squared_error(s.gain,p)**.5,3),"anchor gain",round(gain,4),"target TT",round(490-82/gain,2),"ridge",model[-1].alpha_)
print("Common slope",s.gain.mean(),"RMSE",np.sqrt(np.mean((s.gain-s.gain.mean())**2))); print("High C mean",s.loc[s.C>=.5,"gain"].mean()); print("Linear C slope coefficients",LinearRegression().fit(s[["C"]],s.gain).coef_,LinearRegression().fit(s[["C"]],s.gain).intercept_)'

python -c 'import numpy as np, pandas as pd; from sklearn.model_selection import LeaveOneOut, cross_val_predict; from sklearn.linear_model import Ridge, RidgeCV; from sklearn.pipeline import make_pipeline; from sklearn.preprocessing import StandardScaler; d=pd.read_csv("b3_fatigue_target.csv"); q=d[(d.THT>30)&(d.CT==30)]; cols=[c for c in q.columns if c not in ["TT","target"]]; rows=[]
for key,g in q.groupby(cols):
 if len(g)>1:
  r=dict(zip(cols,key)); r["gain"]=-np.polyfit(g.TT,g.target,1)[0]; r["span"]=g.TT.max()-g.TT.min(); r["actual_gain"]=g.loc[g.TT.idxmin(),"target"]-g.loc[g.TT.idxmax(),"target"]; rows.append(r)
s=pd.DataFrame(rows); fs=["C","Cr","Ni","Mo"]; a=d.loc[d.target.eq(718)].drop(columns="target").iloc[0].copy(); m=make_pipeline(StandardScaler(),RidgeCV(alphas=np.logspace(-2,3,25))); pred=cross_val_predict(m,s[fs],s.gain,cv=LeaveOneOut()); err=pred*s.span-s.actual_gain; print("LOO anchored low-T prediction: MAE",float(np.abs(err).mean()),"RMSE",float(np.sqrt(np.mean(err**2))),"90pct absolute error",float(np.quantile(np.abs(err),.9))); print("High carbon LOO anchored MAE",float(np.abs(err[s.C>=.5]).mean())); m.fit(s[fs],s.gain); gain=float(m.predict(a[fs].to_frame().T)[0]); print("Final slope",gain,"coefs",dict(zip(fs,m[-1].coef_/m[0].scale_))); rng=np.random.default_rng(2026); bs=[]
for i in range(500):
 b=s.iloc[rng.integers(len(s),size=len(s))]; fit=make_pipeline(StandardScaler(),Ridge(alpha=m[-1].alpha_)); fit.fit(b[fs],b.gain); bs.append(float(fit.predict(a[fs].to_frame().T)[0]))
print("Bootstrap gain 5/50/95 percentiles (model-fit uncertainty only)",np.quantile(bs,[.05,.5,.95])); a.TT=423.5; print("Estimated fatigue",718+gain*(490-a.TT)); lo=d.drop(columns="target").min(); hi=d.drop(columns="target").max(); assert ((a>=lo)&(a<=hi)).all(); print("All 25 variables within actual observed ranges:",len(a)); print("Changed from 718 sample:",a[a.ne(d.loc[d.target.eq(718)].drop(columns="target").iloc[0])].to_dict()); print("Recipe:",", ".join(f"{k}={v:g}" for k,v in a.items()))'

